import re
def trick(df, schema, rng, p):
    for col_name, col_type, allowed in schema:
        if col_name not in df.columns:
            continue
        for i in range(len(df)):
            val = df.at[i, col_name]
            if isinstance(val, str) and val and rng.random() < p:
                # Add a prefix of 1-3 characters from the start of the value
                prefix_len = min(rng.randint(1, 3), len(val))
                prefix = val[:prefix_len]
                df.at[i, col_name] = prefix + val
    return df

